import{_ as l,o as i,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Performance Meeting 20180-9-20","description":"","frontmatter":{"title":"Ceph Performance Meeting 20180-9-20","date":"2018-10-17T00:00:00.000Z","updated":"2018-10-18T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","内存分配","QoS"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Ceph_Performance_Meeting_20180-9-20.md","filePath":"posts/2018/Ceph_Performance_Meeting_20180-9-20.md","lastUpdated":1780459816000}'),r={name:"posts/2018/Ceph_Performance_Meeting_20180-9-20.md"};function a(n,e,s,p,c,_){return i(),t("div",null,[...e[0]||(e[0]=[o("<p>在Ceph性能会议中，与会人员讨论了一系列关于Ceph分布式存储系统的性能优化和内存分配的问题。以下是会议的关键细节和讨论的主要内容：</p><p><strong>关键细节</strong>：</p><ul><li><strong>Pull Requests</strong>： Sage移除了不再使用的死代码，并优化了MDS的性能；讨论了容器与slab分配的优化以及使用持久内存作为RBD持久缓存的改进。</li><li><strong>内存分配问题</strong>： 讨论了Ceph在内存分配方面的挑战，包括buffer列表的碎片化、对象池的使用以及TC Malloc分配器。</li><li><strong>性能优化</strong>： 讨论了Ceph在性能方面的挑战，包括CPU使用率、I/O吞吐量以及内存使用率。讨论了使用性能计数器、基准测试和QoS框架来优化性能。</li></ul><p><strong>决定的事项</strong>：</p><ul><li>Sage将负责合并PRS并解释相关改进。</li><li>Mark将继续解决内存分配问题，并探索使用对象池和环形缓冲区的可行性。</li><li>Marcus将创建一个“邪恶列表”，列出Ceph中存在内存分配问题的代码。</li><li>Matt将负责使用性能计数器和基准测试来评估Ceph的性能。</li><li>Shelby将负责使用QoS框架来优化Ceph的性能。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Sage将合并PRS并更新相关代码。</li><li>Mark将探索使用对象池和环形缓冲区的可行性，并解决内存分配问题。</li><li>Marcus将创建一个“邪恶列表”。</li><li>Matt将使用性能计数器和基准测试来评估Ceph的性能。</li><li>Shelby将使用QoS框架来优化Ceph的性能。</li></ul><p><strong>关键词</strong>：</p><ul><li>Pull Requests</li><li>Dead code</li><li>Mutex</li><li>Performance counter</li><li>Heap allocation</li><li>MDS</li><li>Shard</li><li>Persistent memory</li><li>Buffer list</li><li>Object pool</li><li>TC Malloc</li><li>Memory fragmentation</li><li>Performance</li><li>CPU utilization</li><li>I/O throughput</li><li>Quality of Service (QoS)</li><li>Benchmark</li><li>Black box testing</li></ul>",9)])])}const h=l(r,[["render",a]]);export{u as __pageData,h as default};
